private bool UpdateReviewList(bool isReviewed)
{
    string arrID = Request["iptSelectReview"];
    if (arrID == null || arrID.Trim() == "")
    {
        if (isReviewed)
            MsgBox.ShowWarning("Bạn phải chọn ít nhất một công việc để duyệt!");
        else
            MsgBox.ShowWarning("Bạn phải chọn ít nhất một công việc để bỏ duyệt!");
        return false;
    }

    SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
    obj.BeginTransaction();

    int intCount = 0;
    string[] arrSelectedID = arrID.Split(',');
    foreach (RepeaterItem item in rptList.Items)
    {
        HiddenField hidTeachingTimeAddedID = item.FindControl("hidTeachingTimeAddedID") as HiddenField;
        HiddenField hidIsReviewed = item.FindControl("hidIsReviewed") as HiddenField;
        if (hidTeachingTimeAddedID == null || hidTeachingTimeAddedID.Value == "")
            continue;

        bool bolCurrentReviewed = IsTrue(hidIsReviewed != null ? hidIsReviewed.Value : null);
        if (isReviewed && bolCurrentReviewed)
            continue;
        if (!isReviewed && !bolCurrentReviewed)
            continue;

        string strID = hidTeachingTimeAddedID.Value;
        bool bolSelected = false;
        for (int i = 0; i < arrSelectedID.Length; i++)
        {
            if (arrSelectedID[i].Trim() == strID)
            {
                bolSelected = true;
                break;
            }
        }

        if (!bolSelected)
            continue;

        TextBox txtReviewedComment = item.FindControl("txtReviewedComment") as TextBox;
        string strComment = "";
        if (txtReviewedComment != null && isReviewed)
            strComment = txtReviewedComment.Text.Trim();

        object objReviewedDate = isReviewed ? (object)DateTime.Now : DBNull.Value;
        object objReviewedUser = isReviewed ? (object)User.UserName : DBNull.Value;
        string strReviewedComment = isReviewed ? strComment : "";

        if (!obj.ExecNonQuery("SIM_TeachingTimeAdded_UpdateReview",
            "@TeachingTimeAddedID", Convert.ToInt64(strID),
            "@IsReviewed", isReviewed,
            "@ReviewedDate", objReviewedDate,
            "@ReviewedUser", objReviewedUser,
            "@ReviewedComment", strReviewedComment,
            "@UpdatedUser", User.UserName))
        {
            if (isReviewed)
                MsgBox.ShowError("Việc cập nhật duyệt bị lỗi! " + obj.ErrorException.Message);
            else
                MsgBox.ShowError("Việc bỏ duyệt bị lỗi! " + obj.ErrorException.Message);
            return false;
        }
        intCount++;
    }

    if (intCount == 0)
    {
        if (isReviewed)
            MsgBox.ShowWarning("Không có công việc chưa duyệt nào được chọn!");
        else
            MsgBox.ShowWarning("Không có công việc đã duyệt nào được chọn!");
        return false;
    }

    obj.CommitTransaction();
    if (isReviewed)
        MsgBox.ShowInfo("Đã duyệt thành công! Số dòng: " + intCount);
    else
        MsgBox.ShowInfo("Đã bỏ duyệt thành công! Số dòng: " + intCount);

    string strActionLog = "Năm học: " + uYearSemester.YearText + " - HK: " + uYearSemester.Semester;
    string strActionName = isReviewed ? "Quản lý duyệt công việc khác trên web" : "Quản lý bỏ duyệt công việc khác trên web";
    new SystemObject.SYS_ActionLog().WriteActionLog(strActionName, strActionLog, SystemObject.ActionLogType.EDIT, intCount, User.UserName);

    return true;
}

private bool SaveReview()
{
    return UpdateReviewList(true);
}

private bool SaveUnReview()
{
    return UpdateReviewList(false);
}

