    var reviewTipPopup = null;
    var reviewTipPanelId = '<%= udpMain.ClientID %>';

    function GetReviewTipPopup() {
        if (reviewTipPopup == null) {
            reviewTipPopup = document.createElement('div');
            reviewTipPopup.className = 'review-tip-popup';
            document.body.appendChild(reviewTipPopup);
        }
        return reviewTipPopup;
    }

    function HideReviewTipPopup() {
        if (reviewTipPopup != null)
            reviewTipPopup.style.display = 'none';
    }

    function ShowReviewTipPopup(text, clientX, clientY) {
        var popup = GetReviewTipPopup();
        popup.textContent = text;
        popup.style.display = 'block';
        popup.style.left = (clientX + 12) + 'px';
        popup.style.top = (clientY + 12) + 'px';
    }

    function InitReviewListCellTips() {
        var panel = document.getElementById(reviewTipPanelId);
        if (panel == null || panel.getAttribute('data-review-tip') == '1')
            return;

        panel.setAttribute('data-review-tip', '1');
        panel.addEventListener('mouseover', function (e) {
            var ta = e.target;
            if (ta == null || ta.tagName != 'TEXTAREA')
                return;

            var text = (ta.value || '').replace(/^\s+|\s+$/g, '');
            if (text == '') {
                HideReviewTipPopup();
                return;
            }

            ShowReviewTipPopup(text, e.clientX, e.clientY);
        });

        panel.addEventListener('mousemove', function (e) {
            if (reviewTipPopup != null && reviewTipPopup.style.display == 'block') {
                reviewTipPopup.style.left = (e.clientX + 12) + 'px';
                reviewTipPopup.style.top = (e.clientY + 12) + 'px';
            }
        });

        panel.addEventListener('mouseout', function (e) {
            var ta = e.target;
            if (ta != null && ta.tagName == 'TEXTAREA')
                HideReviewTipPopup();
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', InitReviewListCellTips);
    } else {
        InitReviewListCellTips();
    }
